pid_t pid = fork();

if (pid < 0) {
    // Error handling
} else if (pid == 0) {
    // Child process: Execute new program
    char *argv[] = {"/bin/ls", "-l", NULL};
    char *envp[] = {NULL};
    execve(argv[0], argv, envp);
    // execve only returns on failure
    _exit(1); 
} else {
    // Parent process: Wait for child
    int status;
    waitpid(pid, &status, 0);
}
